{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2116-06-06 19:45:00",
      "speaker": "Doctor",
      "text": "Hello, I'm Dr. Lee. I understand you had an episode of vision loss. Can you tell me what happened?"
    },
    {
      "turn_number": 2,
      "time": "2116-06-06 19:46:00",
      "speaker": "Patient",
      "text": "Yes, I was sitting at home watching TV when suddenly everything went completely black. I couldn’t see anything—not even light."
    },
    {
      "turn_number": 3,
      "time": "2116-06-06 19:47:00",
      "speaker": "Doctor",
      "text": "Was it just one eye or both?"
    },
    {
      "turn_number": 4,
      "time": "2116-06-06 19:48:00",
      "speaker": "Patient",
      "text": "Both. It was all at once. I was scared, started breathing fast, and felt sweaty."
    },
    {
      "turn_number": 5,
      "time": "2116-06-06 19:49:00",
      "speaker": "Doctor",
      "text": "Did you have any weakness or trouble walking?"
    },
    {
      "turn_number": 6,
      "time": "2116-06-06 19:50:00",
      "speaker": "Patient",
      "text": "No, I got up and walked to the door when my physical therapist knocked. I couldn’t see, but I know the path well."
    },
    {
      "turn_number": 7,
      "time": "2116-06-06 19:51:00",
      "speaker": "Doctor",
      "text": "How long did the blindness last?"
    },
    {
      "turn_number": 8,
      "time": "2116-06-06 19:52:00",
      "speaker": "Patient",
      "text": "About two hours. Then I blinked and could see, but it was blurry at first. Then it cleared up completely."
    },
    {
      "turn_number": 9,
      "time": "2116-06-06 19:53:00",
      "speaker": "Doctor",
      "text": "You mentioned a headache before it happened?"
    },
    {
      "turn_number": 10,
      "time": "2116-06-06 19:54:00",
      "speaker": "Patient",
      "text": "Yes, a sharp one at the top of my head—like a chisel stabbing me. I don’t usually get headaches like that."
    },
    {
      "turn_number": 11,
      "time": "2116-06-06 19:55:00",
      "speaker": "Doctor",
      "text": "And you’ve had pain in your temples when you sleep on them for the past two weeks?"
    },
    {
      "turn_number": 12,
      "time": "2116-06-06 19:56:00",
      "speaker": "Patient",
      "text": "Yes, it hurts to lie on either side. I’ve never had that before."
    },
    {
      "turn_number": 13,
      "time": "2116-06-06 19:57:00",
      "speaker": "Doctor",
      "text": "We’re going to do a CT scan of your head to check for any bleeding or stroke."
    },
    {
      "turn_number": 14,
      "time": "2116-06-06 20:15:00",
      "speaker": "Doctor",
      "text": "The CT scan is back. Good news—no bleeding or new stroke. But we need more detailed imaging."
    },
    {
      "turn_number": 15,
      "time": "2116-06-06 20:16:00",
      "speaker": "Patient",
      "text": "So what could it be?"
    },
    {
      "turn_number": 16,
      "time": "2116-06-06 20:17:00",
      "speaker": "Doctor",
      "text": "One concern is giant cell arteritis. It’s inflammation in the blood vessels, especially in the temples. It can cause vision loss."
    },
    {
      "turn_number": 17,
      "time": "2116-06-06 20:18:00",
      "speaker": "Patient",
      "text": "Is that serious?"
    },
    {
      "turn_number": 18,
      "time": "2116-06-06 20:19:00",
      "speaker": "Doctor",
      "text": "Yes, it can lead to permanent blindness if not treated. But we’re catching it early. We’ll do an MRI and check your blood work."
    },
    {
      "turn_number": 19,
      "time": "2116-06-07 08:30:00",
      "speaker": "Doctor",
      "text": "Your MRI is done. No new stroke. But we see some chronic changes from past strokes. The occipital lobes, which process vision, look okay."
    },
    {
      "turn_number": 20,
      "time": "2116-06-07 08:31:00",
      "speaker": "Patient",
      "text": "So not a stroke this time?"
    },
    {
      "turn_number": 21,
      "time": "2116-06-07 08:32:00",
      "speaker": "Doctor",
      "text": "No. But your ESR, a marker of inflammation, is elevated at 59. That supports the possibility of giant cell arteritis."
    },
    {
      "turn_number": 22,
      "time": "2116-06-07 08:33:00",
      "speaker": "Patient",
      "text": "What’s the treatment?"
    },
    {
      "turn_number": 23,
      "time": "2116-06-07 08:34:00",
      "speaker": "Doctor",
      "text": "We’re starting you on high-dose prednisone—60 mg daily—to reduce inflammation and protect your vision."
    },
    {
      "turn_number": 24,
      "time": "2116-06-07 08:35:00",
      "speaker": "Patient",
      "text": "Will I have side effects?"
    },
    {
      "turn_number": 25,
      "time": "2116-06-07 08:36:00",
      "speaker": "Doctor",
      "text": "We’ll add famotidine to protect your stomach. And we’ll adjust your diabetes meds—prednisone can raise blood sugar."
    },
    {
      "turn_number": 26,
      "time": "2116-06-07 08:37:00",
      "speaker": "Patient",
      "text": "I already take insulin. Will I need more?"
    },
    {
      "turn_number": 27,
      "time": "2116-06-07 08:38:00",
      "speaker": "Doctor",
      "text": "Yes, we’re increasing your Lantus from 10 to 14 units. And we’re adding Humalog at meals with a sliding scale."
    },
    {
      "turn_number": 28,
      "time": "2116-06-07 08:39:00",
      "speaker": "Patient",
      "text": "Okay. What about the diagnosis? Is it confirmed?"
    },
    {
      "turn_number": 29,
      "time": "2116-06-07 08:40:00",
      "speaker": "Doctor",
      "text": "Not yet. The best way to confirm is a temporal artery biopsy. We’ve consulted vascular surgery."
    },
    {
      "turn_number": 30,
      "time": "2116-06-08 09:00:00",
      "speaker": "Doctor",
      "text": "The surgeon will do the biopsy tomorrow morning. It’s a small procedure—just a sample from one temple."
    },
    {
      "turn_number": 31,
      "time": "2116-06-08 09:01:00",
      "speaker": "Patient",
      "text": "Will it hurt?"
    },
    {
      "turn_number": 32,
      "time": "2116-06-08 09:02:00",
      "speaker": "Doctor",
      "text": "You’ll be numbed, and it’s quick. We do it to confirm the diagnosis and guide long-term treatment."
    },
    {
      "turn_number": 33,
      "time": "2116-06-09 13:00:00",
      "speaker": "Doctor",
      "text": "The biopsy went well. No complications. We’ll get the results in a few days."
    },
    {
      "turn_number": 34,
      "time": "2116-06-09 13:01:00",
      "speaker": "Patient",
      "text": "Am I still at risk for another episode?"
    },
    {
      "turn_number": 35,
      "time": "2116-06-09 13:02:00",
      "speaker": "Doctor",
      "text": "The prednisone helps prevent that. That’s why we started it even before the biopsy."
    },
    {
      "turn_number": 36,
      "time": "2116-06-09 13:03:00",
      "speaker": "Patient",
      "text": "I’ve been checking my sugars more. They’ve been higher, like 202 during the episode."
    },
    {
      "turn_number": 37,
      "time": "2116-06-09 13:04:00",
      "speaker": "Doctor",
      "text": "Exactly why we adjusted your insulin. Keep checking four times a day—fasting, before meals, and bedtime."
    },
    {
      "turn_number": 38,
      "time": "2116-06-09 13:05:00",
      "speaker": "Patient",
      "text": "And my other meds? I take a lot."
    },
    {
      "turn_number": 39,
      "time": "2116-06-09 13:06:00",
      "speaker": "Doctor",
      "text": "We’re simplifying. We lowered your torsemide and amlodipine. Added ezetimibe for cholesterol."
    },
    {
      "turn_number": 40,
      "time": "2116-06-09 13:07:00",
      "speaker": "Patient",
      "text": "I saw my blood pressure was high when I came in—184 over 49."
    },
    {
      "turn_number": 41,
      "time": "2116-06-09 13:08:00",
      "speaker": "Doctor",
      "text": "Yes, your systolic was high, but diastolic low. We’re monitoring it. The hydralazine and metoprolol are helping."
    },
    {
      "turn_number": 42,
      "time": "2116-06-10 07:00:00",
      "speaker": "Doctor",
      "text": "Good news. You’re being discharged today. Your condition is stable."
    },
    {
      "turn_number": 43,
      "time": "2116-06-10 07:01:00",
      "speaker": "Patient",
      "text": "So I’m okay to go home?"
    },
    {
      "turn_number": 44,
      "time": "2116-06-10 07:02:00",
      "speaker": "Doctor",
      "text": "Yes, with home health services. You’ll have help with nursing and therapy."
    },
    {
      "turn_number": 45,
      "time": "2116-06-10 07:03:00",
      "speaker": "Patient",
      "text": "What about the biopsy results?"
    },
    {
      "turn_number": 46,
      "time": "2116-06-10 07:04:00",
      "speaker": "Doctor",
      "text": "They’re pending. You must follow up with your neurologist and primary care doctor. They’ll decide if you continue prednisone."
    },
    {
      "turn_number": 47,
      "time": "2116-06-10 07:05:00",
      "speaker": "Patient",
      "text": "How long will I take the prednisone?"
    },
    {
      "turn_number": 48,
      "time": "2116-06-10 07:06:00",
      "speaker": "Doctor",
      "text": "At least two weeks. Then your doctor will taper it slowly, depending on the biopsy and your symptoms."
    },
    {
      "turn_number": 49,
      "time": "2116-06-10 07:07:00",
      "speaker": "Patient",
      "text": "And my vision? It’s back to normal."
    },
    {
      "turn_number": 50,
      "time": "2116-06-10 07:08:00",
      "speaker": "Doctor",
      "text": "That’s excellent. The treatment is working. But call immediately if it happens again—or if you get jaw pain, scalp tenderness, or new headaches."
    },
    {
      "turn_number": 51,
      "time": "2116-06-10 07:09:00",
      "speaker": "Patient",
      "text": "I will. Thank you for explaining everything."
    },
    {
      "turn_number": 52,
      "time": "2116-06-10 07:10:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Keep checking your sugars, take your meds, and keep those follow-up appointments."
    },
    {
      "turn_number": 53,
      "time": "2116-06-10 07:11:00",
      "speaker": "Patient",
      "text": "I have my walker and I’m steady on my feet. I think I’ll be okay at home."
    },
    {
      "turn_number": 54,
      "time": "2116-06-10 07:12:00",
      "speaker": "Doctor",
      "text": "Yes, you’re doing well. Just take it slow and call if anything changes."
    },
    {
      "turn_number": 55,
      "time": "2116-06-10 07:13:00",
      "speaker": "Patient",
      "text": "One more thing—my temple hurts where they did the biopsy."
    },
    {
      "turn_number": 56,
      "time": "2116-06-10 07:14:00",
      "speaker": "Doctor",
      "text": "That’s normal. The stitches are dissolvable. It should improve in a few days."
    },
    {
      "turn_number": 57,
      "time": "2116-06-10 07:15:00",
      "speaker": "Patient",
      "text": "And the famotidine? Do I keep taking that?"
    },
    {
      "turn_number": 58,
      "time": "2116-06-10 07:16:00",
      "speaker": "Doctor",
      "text": "Yes, once daily, to protect your stomach while on prednisone. Your doctor will advise when to stop."
    },
    {
      "turn_number": 59,
      "time": "2116-06-10 07:17:00",
      "speaker": "Patient",
      "text": "Got it. I’ll follow up with my doctors and monitor everything."
    },
    {
      "turn_number": 60,
      "time": "2116-06-10 07:18:00",
      "speaker": "Doctor",
      "text": "Perfect. You’ve been very proactive. Take care, and we’ll see you in follow-up if needed."
    }
  ],
  "summary": {
    "admission_start": "2116-06-06 19:33:00",
    "admission_end": "2116-06-10 18:00:00",
    "summary_paragraph": "The patient was admitted following a two-hour episode of transient bilateral visual loss, accompanied by a severe vertex headache, bilateral temporal tenderness, jaw stiffness, and shoulder pain. Imaging showed no acute stroke but revealed chronic infarcts and vascular changes. Elevated ESR and clinical symptoms raised strong suspicion for giant cell arteritis. The patient was started on high-dose prednisone and famotidine, with adjustments to insulin therapy due to steroid-induced hyperglycemia. A temporal artery biopsy was performed without complications, though results were pending at discharge. The patient’s vision returned to baseline, and she was discharged home with home health services, with instructions to follow up on biopsy results and medication management.",
    "problems": [
      "Transient visual loss",
      "Headache",
      "Other late effects of cerebrovascular disease",
      "Diabetes with neurological manifestations, type II or unspecified type, not stated as uncontrolled",
      "Diabetes with ophthalmic manifestations, type II or unspecified type, not stated as uncontrolled",
      "Background diabetic retinopathy",
      "Diabetes with renal manifestations, type II or unspecified type, not stated as uncontrolled",
      "Coronary atherosclerosis of unspecified type of vessel, native or graft",
      "Aortocoronary bypass status",
      "Unspecified essential hypertension",
      "Other and unspecified hyperlipidemia",
      "Asthma, unspecified type, unspecified"
    ]
  }
}
